function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('bnt-design-lab-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onerror=()=>reject(r.error);r.onsuccess=()=>resolve(r.result);});}
function readDB(){return new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get('main');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function persist(){dirty=true;$('#saveState').textContent='保存中';const snapshot=structuredClone(state);const job=queued.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(!db)return reject(Error('DB unavailable'));const tx=db.transaction('state','readwrite');tx.objectStore('state').put(snapshot,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);}));queued=job;job.then(()=>{if(queued===job){dirty=false;$('#saveState').textContent='この端末に保存済み';}}).catch(()=>{$('#saveState').textContent='保存失敗';message('保存できません 下書きを書き出して保管してください');});return job;}
