function filtered(){const pool=scope==='local'?state.posts:allPosts();return pool.filter(p=>(view!=='images'||p.blocks.some(b=>b.type==='image'))&&(view!=='articles'||prose(p).trim())&&(!tag||p.tags.includes(tag))&&(!search||[p.title,prose(p),...p.tags].join(' ').toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>sort==='title'?(a.title||prose(a)).localeCompare(b.title||prose(b),'ja'):sort==='old'?(a.date||'').localeCompare(b.date||''):(b.date||'').localeCompare(a.date||''));}
function render(){const posts=filtered();$('#feed').className='feed '+(layout==='list'?'list':'');$('#empty').hidden=!!posts.length;$('#pageTitle').textContent=search?'検索結果':tag|| (scope==='local'?'この端末の投稿':'投稿一覧');$('#activeFilters').innerHTML=[search?`<span>検索 ${esc(search)}</span>`:'',tag?`<span>${esc(tag)}</span>`:'',(tag||search||scope==='local')?'<button id="resetSearch">条件を解除</button>':''].join('');$('#resetSearch')?.addEventListener('click',clearFilters);
$('#feed').innerHTML=posts.map(p=>{const images=p.blocks.filter(b=>b.type==='image');const body=prose(p);return `<button class="post" data-id="${esc(p.id)}" aria-label="${esc(p.title||body.slice(0,35)||'画像の投稿')}を開く"><div class="cover ${images.length?'':'textcover'}">${images.length?`<img src="${esc(images[0].src)}" alt="${esc(images[0].alt||'投稿画像')}" loading="lazy">${images.length>1?'<span class="imageflag">複数画像</span>':''}`:`<p>${esc(body||p.title)}</p>`}</div><div class="postbody">${p.title?`<h2>${esc(p.title)}</h2>`:''}<div class="meta">${dateLabel(p)}${p.sample?'':'　端末内'}</div><div class="category">${p.tags.map(esc).join(' / ')}</div><p class="excerpt">${esc(body.slice(0,220))}</p></div></button>`;}).join('');$$('#feed .post').forEach(el=>el.onclick=()=>openDetail(posts.find(p=>p.id===el.dataset.id)));
const themes=['すべて',...new Set(allPosts().flatMap(p=>p.tags))];$('#themes').innerHTML=themes.map(t=>`<button data-tag="${esc(t)}" class="${(t==='すべて'&&!tag)||tag===t?'active':''}">${esc(t)}</button>`).join('');$$('#themes button').forEach(b=>b.onclick=()=>{tag=b.dataset.tag==='すべて'?'':b.dataset.tag;render();});}
function clearFilters(){search='';tag='';scope='all';view='all';$('#search').value='';$$('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.view==='all')));render();}
function renderContent(p){return `<div class="rendered"><div class="hint">${dateLabel(p)} ${p.tags.map(esc).join(' / ')}</div>${p.title?`<h1>${esc(p.title)}</h1>`:''}${p.blocks.map(b=>b.type==='image'?`<figure><img src="${esc(b.src)}" alt="${esc(b.alt||'投稿画像')}">${b.alt?`<figcaption>${esc(b.alt)}</figcaption>`:''}</figure>`:b.type==='heading'?`<h2>${esc(b.text)}</h2>`:b.type==='quote'?`<blockquote>${esc(b.text)}</blockquote>`:b.type==='link'?`<p>${/^https?:\/\//i.test(b.url)?`<a href="${esc(b.url)}" target="_blank" rel="noopener noreferrer">${esc(b.text||b.url)}</a>`:'リンク先を確認してください'}</p>`:`<p>${esc(b.text)}</p>`).join('')}</div>`;}
function openDetail(p,preview=false){$('#detailLabel').textContent=preview?'プレビュー':p.sample?'表示見本':'この端末の投稿';$('#detailContent').innerHTML=renderContent(p);$('#detailActions').innerHTML=preview?'':`<button id="editDetail">${p.sample?'コピーして編集':'編集'}</button>${p.sample?'':'<button id="privateDetail">下書きに戻す</button>'}`;if(!preview){$('#editDetail').onclick=()=>{if(state.draft&&state.draft.id!==p.id){message('編集中の下書きがあります 下書きから再開してください');return;}$('#detail').close();openEditor(p);};if($('#privateDetail'))$('#privateDetail').onclick=async()=>{if(state.draft&&state.draft.id!==p.id){message('先に編集中の下書きを保存してください');return;}const before=structuredClone(state);state.draft=structuredClone(p);state.posts=state.posts.filter(x=>x.id!==p.id);try{await persist();$('#detail').close();render();message('下書きに戻しました');}catch{state=before;}};}$('#detail').showModal();}
function resize(el){el.style.height='0';el.style.height=Math.max(46,el.scrollHeight)+'px';}
function focusPiece(i){activeIndex=i;const b=editing.blocks[i];$('#format').value=['paragraph','heading','quote'].includes(b?.type)?b.type:'paragraph';}
function ensureTrailing(){if(!editing.blocks.length||editing.blocks.at(-1).type!=='paragraph')editing.blocks.push(textBlock(''));}
function drawWriting(){ensureTrailing();$('#writing').classList.toggle('arranging',arranging);$('#writing').innerHTML=editing.blocks.map((b,i)=>`<div class="piece ${esc(b.type)}" data-index="${i}"><div class="piececontrols"><button data-move="-1" ${i===0?'disabled':''} aria-label="上へ移動">上へ</button><button data-move="1" ${i===editing.blocks.length-1?'disabled':''} aria-label="下へ移動">下へ</button><button data-remove>削除</button></div>${b.type==='image'?`<figure><img src="${esc(b.src)}" alt="${esc(b.alt||'投稿画像')}"><input data-field="alt" value="${esc(b.alt)}" placeholder="画像の説明 任意" aria-label="画像の説明"></figure>`:b.type==='link'?`<input data-field="text" value="${esc(b.text)}" aria-label="リンクの表示名"><input class="url" data-field="url" value="${esc(b.url)}" aria-label="リンク先URL">`:`<textarea data-field="text" aria-label="${b.type==='heading'?'見出し':b.type==='quote'?'引用':'本文'}" placeholder="${i===0?'本文を入力 または画像を追加':'本文を入力'}" rows="1">${esc(b.text)}</textarea>`}</div>`).join('');
$$('#writing .piece').forEach(el=>{const i=Number(el.dataset.index);el.querySelectorAll('[data-field]').forEach(input=>{input.onfocus=()=>focusPiece(i);input.oninput=()=>{editing.blocks[i][input.dataset.field]=input.value;if(input.tagName==='TEXTAREA')resize(input);collect();};if(input.tagName==='TEXTAREA'){resize(input);input.onpaste=e=>{const imgs=[...e.clipboardData.files].filter(f=>f.type.startsWith('image/'));if(imgs.length){e.preventDefault();addFiles(imgs,captureInsertion());}};}});el.querySelectorAll('[data-move]').forEach(btn=>btn.onclick=()=>{const n=i+Number(btn.dataset.move);[editing.blocks[i],editing.blocks[n]]=[editing.blocks[n],editing.blocks[i]];activeIndex=n;drawWriting();collect();});el.querySelector('[data-remove]').onclick=()=>{const removed=editing.blocks.splice(i,1)[0];drawWriting();collect();message('削除しました');const undo=document.createElement('button');undo.textContent='元に戻す';const editorId=editing.id;undo.onclick=()=>{if(editing?.id===editorId&&$('#editor').open){editing.blocks.splice(i,0,removed);drawWriting();collect();}$('#toast').hidden=true;};$('#toast').append(undo);clearTimeout(message.timer);message.timer=setTimeout(()=>$('#toast').hidden=true,15000);};});}
function openEditor(p){editing=structuredClone(p?(p.sample?{...p,id:id(),sample:false}:p):(state.draft||{id:id(),title:'',tags:[],date:localDate(),blocks:[textBlock('')]}));$('#title').value=editing.title;$('#tags').value=editing.tags.join(' ');$('#date').value=editing.date;arranging=false;activeIndex=0;$('#arrange').setAttribute('aria-pressed','false');$('#editorTitle').textContent=state.posts.some(x=>x.id===editing.id)?'投稿を編集':'投稿';$('#publishButton').textContent=state.posts.some(x=>x.id===editing.id)?'変更を保存':'一覧に追加';$('#editor').showModal();drawWriting();collect();$('#writing textarea')?.focus();}
function captureInsertion(){const i=Math.min(activeIndex,editing.blocks.length-1);const field=$(`#writing .piece[data-index="${i}"] textarea`);return {index:i,caret:field?field.selectionStart:null};}
function insert(items,position){const i=position.index;const current=editing.blocks[i];if(current&&['paragraph','heading','quote'].includes(current.type)&&position.caret!==null){const before=current.text.slice(0,position.caret),after=current.text.slice(position.caret);editing.blocks.splice(i,1,{...current,text:before},...items,textBlock(after));activeIndex=i+items.length+1;}else{editing.blocks.splice(i+1,0,...items,textBlock(''));activeIndex=i+items.length+1;}drawWriting();collect();$(`#writing .piece[data-index="${activeIndex}"] textarea`)?.focus();}
let filePosition=null,linkPosition=null;
function setUploading(value){uploading=value;$('#uploadState').textContent=value?'画像を読み込み中':'外部には公開されません';['#closeEditor','#publishButton','#previewButton','#addImage','#format','#addLink','#arrange'].forEach(s=>$(s).disabled=value);$('#writing').inert=value;}
async function addFiles(files,position){if(uploading)return;setUploading(true);const items=[];let bytes=editing.blocks.reduce((n,b)=>n+(b.bytes||0),0);try{for(const f of files){if(!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type)||f.size>8*1024*1024||bytes+f.size>30*1024*1024){message('画像を追加できません 形式と容量を確認してください');continue;}try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});await new Promise((resolve,reject)=>{const im=new Image();im.onload=resolve;im.onerror=reject;im.src=src;});items.push({...imgBlock(src,''),bytes:f.size});bytes+=f.size;}catch{message('画像を読み取れません');}}if(items.length)insert(items,position||captureInsertion());}finally{setUploading(false);$('#file').value='';}}
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$$('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();});$$('[data-layout]').forEach(b=>b.onclick=()=>{layout=b.dataset.layout;$$('[data-layout]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();});$('#sort').onchange=e=>{sort=e.target.value;render();};$('#search').oninput=e=>{search=e.target.value;render();};$('#searchForm').onsubmit=e=>{e.preventDefault();search=$('#search').value;render();};$('#brand').onclick=clearFilters;$('#allButton').onclick=clearFilters;$('#clearFilters').onclick=clearFilters;$('#localButton').onclick=()=>{scope='local';render();};$('#collectionsButton').onclick=()=>{const topics=[...new Set(allPosts().flatMap(p=>p.tags))];$('#detailLabel').textContent='作品集';$('#detailContent').innerHTML='<div class="collectionlinks">'+topics.map(t=>`<button data-topic="${esc(t)}">${esc(t)}</button>`).join('')+'</div>';$('#detailActions').innerHTML='';$$('[data-topic]').forEach(b=>b.onclick=()=>{clearFilters();tag=b.dataset.topic;render();$('#detail').close();});$('#detail').showModal();};
$('#newButton').onclick=()=>openEditor();$('#draftButton').onclick=()=>state.draft?openEditor():message('下書きはありません');$('#addImage').onclick=()=>{filePosition=captureInsertion();$('#file').click();};$('#file').onchange=e=>addFiles(e.target.files,filePosition);$('#format').onchange=e=>{const b=editing.blocks[activeIndex];if(b&&['paragraph','heading','quote'].includes(b.type)){b.type=e.target.value;drawWriting();collect();$(`#writing .piece[data-index="${activeIndex}"] textarea`)?.focus();}else message('書式を変える文章を選んでください');};$('#arrange').onclick=()=>{arranging=!arranging;$('#arrange').setAttribute('aria-pressed',String(arranging));$('#writing').classList.toggle('arranging',arranging);};$('#addLink').onclick=()=>{linkPosition=captureInsertion();$('#linkName').value='';$('#linkUrl').value='';$('#linkDialog').showModal();};$('#cancelLink').onclick=()=>$('#linkDialog').close();$('#linkForm').onsubmit=e=>{e.preventDefault();const url=$('#linkUrl').value.trim();if(!/^https?:\/\//i.test(url)){message('http または https のURLを入力してください');return;}insert([{id:id(),type:'link',text:$('#linkName').value||url,url}],linkPosition);$('#linkDialog').close();};
[$('#title'),$('#tags'),$('#date')].forEach(x=>x.oninput=collect);$('#closeEditor').onclick=()=>{collect();$('#editor').close();render();};$('#editor').addEventListener('cancel',e=>{if(uploading){e.preventDefault();message('画像の読み込み完了をお待ちください');}else{collect();render();}});$('#closeDetail').onclick=()=>$('#detail').close();$('#previewButton').onclick=()=>openDetail(editing,true);
$('#publishButton').onclick=async()=>{if(uploading)return;if(!editing.blocks.some(b=>b.type==='image'||(b.text||'').trim())){message('画像か本文を追加してください');return;}collect();const next=structuredClone(editing),before=structuredClone(state);state.posts=[next,...state.posts.filter(p=>p.id!==next.id)];state.draft=null;$('#publishButton').disabled=true;try{await persist();$('#editor').close();clearFilters();message('この端末に保存しました');}catch{state=before;}finally{$('#publishButton').disabled=false;}};
$('#exportButton').onclick=()=>{collect();const data=JSON.stringify({schemaVersion:1,prototype:true,post:editing},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='brand-new-tokyo-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#editor').addEventListener('dragover',e=>e.preventDefault());$('#editor').addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length)addFiles(e.dataTransfer.files,captureInsertion());});window.addEventListener('beforeunload',e=>{if(dirty||uploading){e.preventDefault();e.returnValue='';}});
$('#newButton').disabled=true;$('#draftButton').disabled=true;(async()=>{try{db=await openDB();const saved=await readDB();if(saved?.posts&&Array.isArray(saved.posts))state=saved;}catch{message('端末保存を利用できません 下書きを書き出して保管してください');}$('#newButton').disabled=false;$('#draftButton').disabled=false;render();})();
